package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.nio.file.Path;

import org.eclipse.rdf4j.common.order.StatementOrder;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailException;
import org.eclipse.rdf4j.sail.lmdb.TxnManager.Txn;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullAndEmptySource;
import org.junit.jupiter.params.provider.ValueSource;

/** Legacy permutation preferences remain accepted and validated without becoming persistent tuple indexes. */
class LmdbPersistentAdjacencyConfigurationTest {

	@TempDir
	Path directory;

	@ParameterizedTest
	@NullAndEmptySource
	@ValueSource(strings = { "spoc", "cspo,opsc,spoc", "SPOC, posc\tcosp" })
	void validLegacySpecificationsPreserveStatementsAcrossReopen(String specification) throws Exception {
		try (TripleStore store = new TripleStore(directory.toFile(), config(specification), null)) {
			store.startTransaction();
			store.storeTriple(10, 20, 30, 0, true);
			store.commit();
		}
		try (TripleStore reopened = new TripleStore(directory.toFile(), config("posc,spoc"), null);
				Txn snapshot = reopened.getTxnManager().createReadTxn();
				RecordIterator statements = reopened.getTriples(snapshot, -1, -1, -1, -1, true)) {
			assertThat(statements.next()).containsExactly(10, 20, 30, 0);
			assertThat(statements.next()).isNull();
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "spoo", "spoc,bogus", "spocs", "s,p,o,c" })
	void malformedSpecificationsFailBeforeOpeningNativeStorage(String specification) {
		Path storage = directory.resolve("triples");
		assertThatThrownBy(() -> {
			try (TripleStore ignored = new TripleStore(storage.toFile(), config(specification), null)) {
				// Construction must reject malformed preferences even though adjacency owns the physical schema.
			}
		}).isInstanceOf(SailException.class).hasMessageContaining("invalid value");
		assertThat(storage).doesNotExist();
	}

	@ParameterizedTest
	@ValueSource(strings = { "spoo", "spoc,bogus" })
	void malformedReopenLeavesTheCommittedAdjacencyReadable(String specification) throws Exception {
		try (TripleStore store = new TripleStore(directory.toFile(), config("spoc"), null)) {
			store.startTransaction();
			store.storeTriple(10, 20, 30, 7, true);
			store.commit();
		}
		assertThatThrownBy(() -> {
			try (TripleStore ignored = new TripleStore(directory.toFile(), config(specification), null)) {
				// Reopening an existing authority applies the same configuration validation as a new store.
			}
		}).isInstanceOf(SailException.class).hasMessageContaining("invalid value");
		try (TripleStore reopened = new TripleStore(directory.toFile(), config("posc"), null);
				Txn snapshot = reopened.getTxnManager().createReadTxn();
				RecordIterator statements = reopened.getTriples(snapshot, -1, -1, -1, -1, true)) {
			assertThat(statements.next()).containsExactly(10, 20, 30, 7);
			assertThat(statements.next()).isNull();
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "cspo,spoc,posc", "spco,spoc,posc" })
	void configuredLogicalOrdersSurviveReopenWithoutRepeatingConfiguration(String specification) throws Exception {
		var values = SimpleValueFactory.getInstance();
		var subject = values.createIRI("urn:logical-order:subject");
		var predicate = values.createIRI("urn:logical-order:predicate");
		String preferred = specification.substring(0, 4);
		LmdbStore initial = new LmdbStore(directory.toFile(), config(specification));
		initial.init();
		try (var connection = initial.getConnection()) {
			connection.begin();
			connection.addStatement(subject, predicate, values.createLiteral(1),
					values.createIRI("urn:logical-order:graph-a"));
			connection.addStatement(subject, predicate, values.createLiteral(2),
					values.createIRI("urn:logical-order:graph-b"));
			connection.commit();
			assertThat(initial.getBackingStore().getTripleStore().getIndexName(-1, -1, -1, -1))
					.isEqualTo(preferred);
		} finally {
			initial.shutDown();
		}
		for (int reopen = 0; reopen < 2; reopen++) {
			LmdbStore store = new LmdbStore(directory.toFile(), config(null));
			store.init();
			try (var connection = store.getConnection()) {
				assertThat(connection.size()).isEqualTo(2L);
				TripleStore triples = store.getBackingStore().getTripleStore();
				assertThat(triples.getIndexName(-1, -1, -1, -1)).isEqualTo(preferred);
				ValueStore dictionary = (ValueStore) store.getValueFactory();
				long subjectId = dictionary.getId(subject);
				long predicateId = dictionary.getId(predicate);
				assertThat(triples.getIndexName(StatementOrder.C, subjectId, predicateId, -1, -1))
						.isEqualTo(preferred);
				try (Txn snapshot = triples.getTxnManager().createReadTxn();
						RecordIterator rows = triples.getTriples(snapshot, StatementOrder.C,
								subjectId, predicateId, -1, -1, true)) {
					long[] first = rows.next().clone();
					long[] second = rows.next().clone();
					assertThat(Long.compareUnsigned(first[3], second[3])).isLessThan(0);
					assertThat(rows.next()).isNull();
				}
			} finally {
				store.shutDown();
			}
		}
	}

	private static LmdbStoreConfig config(String specification) {
		return new LmdbStoreConfig(specification).setForceSync(true);
	}
}
